namespace ghidra.app.plugin.core.functiongraph.graph.vertex;








using docking;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util.table;
using ghidra.util.table.field;

public class XRefChooserDialog : DialogComponentProvider {

	private GhidraTable table;
	private GhidraTableFilterPanel<ReferenceEndpoint> filterPanel;

	private Program program;
	private ServiceProvider serviceProvider;
	private List<Reference> references;

	public XRefChooserDialog(List<Reference> references, Program program,
			ServiceProvider serviceProvider) : base("Jump to XRef")
    {
		this.references = references;
		this.program = program;
		this.serviceProvider = serviceProvider;

		setPreferredSize(400, 400);

		addOKButton();
		addCancelButton();
		addWorkPanel(createWorkPanel());

		setOkEnabled(false);
	}

	private JComponent createWorkPanel() {
		JPanel workPanel = new JPanel(new BorderLayout());

		ReferencesFromTableModel model =
			new ReferencesFromTableModel(references, serviceProvider, program);
		table = new GhidraTable(model);
		table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);

		table.addMouseListener(new _Anon_MouseAdapter_1());

		table.getSelectionModel().addListSelectionListener(e => {
			if (e.getValueIsAdjusting()) {
				return;
			}

			setOkEnabled(table.getSelectedRow() != -1);
		});

		filterPanel = new(table, model);
		filterPanel.getAccessibleContext().setAccessibleName("Filter");
		workPanel.add(new JScrollPane(table), BorderLayout.CENTER);
		workPanel.add(filterPanel, BorderLayout.SOUTH);
		workPanel.getAccessibleContext().setAccessibleName("External Reference Chooser");
		return workPanel;
	}

	/* @Override */
	protected void okCallback() {
		int selectedRow = table.getSelectedRow();
		if (selectedRow == -1) {
			setStatusText("You must make a selection or press Cancel");
			return;
		}

		close();
	}

	/* @Override */
	public void close() {
		base.close();
		filterPanel.dispose();
	}

	/* @Override */
	protected void cancelCallback() {
		table.clearSelection();
		close();
	}

	public Reference getSelectedReference() {
		int selectedRow = table.getSelectedRow();
		int modelRow = filterPanel.getModelRow(selectedRow);
		if (modelRow == -1) {
			return null;
		}

		return references.get(modelRow);
	}

	internal class _Anon_MouseAdapter_1 : MouseAdapter
	{

			/* @Override */
			public void mouseClicked(MouseEvent e) {
				if (e.getClickCount() < 2) {
					return;
				}

				int row = table.rowAtPoint(e.getPoint());
				if (row == -1) {
					return; // not sure if this can happen
				}

				okCallback();
			}
		
	}

}
